<?php
require __DIR__.'/app/bootstrap.php';require __DIR__.'/app/site-access.php';$u=require_user();header('Content-Type: text/html; charset=utf-8');
$error='';$articles=[];$siteFilter=max(0,(int)($_GET['site_id']??0));$statusFilter=(string)($_GET['status']??'');$search=trim((string)($_GET['q']??''));$termId=max(0,(int)($_GET['term_id']??0));$sites=[];$total=0;
try{
 $pdo=db();
 $allowed=allowed_primary_sites($pdo,$u);
 $sites=$pdo->query('SELECT id,name FROM sites ORDER BY name')->fetchAll();
 $sites=array_values(array_filter($sites,fn($s)=>in_array((int)$s['id'],$allowed,true)));
 if($siteFilter&&!in_array($siteFilter,$allowed,true))throw new RuntimeException('Nincs jogosultság a webhelyhez.');
 if(!in_array($statusFilter,['','draft','review','scheduled','published','archived'],true))$statusFilter='';
 $where=['a.site_id IN ('.implode(',',array_map('intval',$allowed?:[-1])).')'];$params=[];
 if($siteFilter){$where[]='a.site_id=?';$params[]=$siteFilter;}
 if($statusFilter!==''){$where[]='a.status=?';$params[]=$statusFilter;}
 if($search!==''){$where[]='a.title LIKE ?';$params[]='%'.mb_substr($search,0,100).'%';}
 if($termId){$where[]='EXISTS (SELECT 1 FROM article_terms at WHERE at.article_id=a.id AND at.term_id=?)';$params[]=$termId;}
 $sql=' FROM articles a JOIN sites s ON s.id=a.site_id WHERE '.implode(' AND ',$where);
 $q=$pdo->prepare('SELECT COUNT(*)'.$sql);$q->execute($params);$total=(int)$q->fetchColumn();
 $q=$pdo->prepare('SELECT a.id,a.title,a.status,a.updated_at,s.name site'.$sql.' ORDER BY a.updated_at DESC LIMIT 100');$q->execute($params);$articles=$q->fetchAll();
}catch(Throwable $e){$error=$e instanceof PDOException?'Az adatbázis nem érhető el.':$e->getMessage();error_log('articles: '.$e->getMessage());}
?><!doctype html><html lang="hu"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>comesy Editor · Cikkek</title><link rel="stylesheet" href="/assets/ui.css"><script src="/assets/ui.js" defer></script><style>body{font-family:system-ui;margin:0}.wrap{max-width:1100px;margin:auto;padding:24px}.head{display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap}.btn{background:#315fd6;color:white;padding:12px 17px;border-radius:8px}.card{padding:24px;margin-top:20px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:13px;border-bottom:1px solid var(--line)}@media(max-width:600px){.wrap{padding:14px}th:nth-child(3),td:nth-child(3){display:none}}</style></head><body><?php require __DIR__.'/app/header.php'; ?><main class="wrap"><div class="head"><h1>Cikkek<?php if(!empty($termId)):?> · Besorolás #<?=(int)$termId?><?php endif;?></h1><a class="btn" href="/editor.php">+ Új cikk</a></div><?php if($error):?><p><?=h($error)?></p><?php endif;?><form method="get" class="comesy-filters"><label class="comesy-search"><span>Keresés</span><input name="q" type="search" value="<?=h($search)?>" placeholder="Cím keresése…"></label><label><span>Webhely</span><select name="site_id"><option value="0">Összes webhely</option><?php foreach($sites as $s):?><option value="<?=(int)$s['id']?>" <?=$siteFilter===(int)$s['id']?'selected':''?>><?=h($s['name'])?></option><?php endforeach;?></select></label><label><span>Státusz</span><select name="status"><option value="">Összes státusz</option><?php foreach(['draft'=>'Piszkozat','review'=>'Ellenőrzés','scheduled'=>'Időzített','published'=>'Publikált','archived'=>'Archivált'] as $key=>$label):?><option value="<?=$key?>" <?=$statusFilter===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><button type="submit">Szűrés</button></form><p><?=$total?> találat<?= $total>100?' · az első 100 látható':''?></p><div class="card comesy-list-card"><table class="comesy-article-table"><thead><tr><th>Cím</th><th>Webhely</th><th>Státusz</th><th>Utolsó módosítás</th></tr></thead><tbody id="article-list"><?php foreach($articles as $a):?><tr data-status="<?=h($a['status'])?>"><td><a href="/editor.php?id=<?=(int)$a['id']?>"><?=h($a['title'])?></a></td><td><?=h($a['site'])?></td><td><?=h(['draft'=>'Piszkozat','review'=>'Ellenőrzés','scheduled'=>'Időzített','published'=>'Publikált','archived'=>'Archivált'][$a['status']]??$a['status'])?></td><td><?=h($a['updated_at'])?></td></tr><?php endforeach;?></tbody></table><p class="comesy-empty-filter" data-empty-for="article-list" hidden>Nincs a szűrésnek megfelelő cikk.</p><?php if(!$articles):?><p>Még nincs mentett cikk.</p><?php endif;?></div></main></body></html>
